-- Venue Live Guest "Lamaran Orient Express". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara orient), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'orient', 'Lamaran Orient Express', 'orient', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 159, 'center 38%',
  $t${"name":"Lamaran Orient Express","orn":"diamond","ui":{"ivory":"#FBF3EA","white":"#FFFFFF","soft":"#EFD8C6","soft2":"#C9964A","accent":"#8A1F33","deep":"#4A1220","ink":"#3E1A22","mute":"#957A6E","line":"#EAD3BE","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FFF9F1","ink":"#3E1A22","accent":"#8A1F33","gold":"#D9A93F","leaf":"#EFD8C6","hbg":"rgba(251,243,234,.94)","hline":"#D9A93F","motif":"diamond"},"hud":{"bg":"rgba(74,18,32,.9)","acc":"#F2D27A","on":"#4A1220"},"scr":{"wine":"#7A1F2B","veil":"251,243,234"}}$t$::jsonb
